<template><div class="min-h-full bg-background p-6"><div class="mx-auto max-w-7xl"><div class="mb-6 flex items-end justify-between"><div><p class="text-xs font-bold uppercase text-primary">Offplan sales</p><h1 class="text-2xl font-black">Offplan Payment Plans</h1></div><button @click="addOpen=true" class="bg-primary px-5 py-2.5 font-bold text-white">+ New payment plan</button></div><div class="mb-4 flex gap-3 border bg-white p-4"><input v-model="search" class="w-full border p-2.5" placeholder="Search plans, type, frequency or application"/><button @click="load" class="border px-4">Refresh</button></div><div class="overflow-x-auto border bg-white"><table class="min-w-full text-left"><thead class="bg-slate-50"><tr><th class="p-4">Type</th><th class="p-4">Frequency</th><th class="p-4">Amount</th><th class="p-4">Due</th><th class="p-4">Installment</th><th class="p-4">Completed</th><th class="p-4 text-right">Actions</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id" class="border-t"><td class="p-4 font-bold">{{x.payment_type||'—'}}</td><td class="p-4">{{x.frequency||'—'}}</td><td class="p-4">{{x.amount||'—'}}</td><td class="p-4">{{x.due_date||'—'}}</td><td class="p-4">{{x.installment_number||'—'}} / {{x.total_installments||'—'}}</td><td class="p-4">{{x.is_completed?'Yes':'No'}}</td><td class="p-4 text-right"><router-link :to="{name:'OffplanPaymentPlan-detail',params:{id:x.id}}" class="border px-3 py-2 text-xs">View</router-link> <button @click="edit(x.id)" class="border border-primary px-3 py-2 text-xs text-primary">Edit</button></td></tr></tbody></table><div v-if="!loading&&!filtered.length" class="p-10 text-center text-slate-500">No payment plans found.</div></div></div><AddOffplanPaymentPlan :open="addOpen" @close="addOpen=false" @saved="load"/><EditOffplanPaymentPlan :open="editOpen" :id="selectedId" @close="editOpen=false" @saved="load"/></div></template><script>import AddOffplanPaymentPlan from "./AddOffplanPaymentPlan.vue";import EditOffplanPaymentPlan from "./EditOffplanPaymentPlan.vue";export default{name:"ViewOffplanPaymentPlan",components:{AddOffplanPaymentPlan,EditOffplanPaymentPlan},data(){return{items:[],search:"",loading:false,addOpen:false,editOpen:false,selectedId:null}},computed:{filtered(){const q=this.search.toLowerCase().trim();return q?this.items.filter(x=>[x.id,x.payment_type,x.frequency,x.amount,x.due_date,x.application].join(" ").toLowerCase().includes(q)):this.items}},mounted(){this.load()},methods:{async load(){this.loading=true;try{const r=await this.$apiGet("/get_offplan_payment_plans");const d=r?.data?.data||r?.data||r?.payment_plans||r;this.items=Array.isArray(d)?d:(d?.results||[])}catch(e){}finally{this.loading=false}},edit(id){this.selectedId=id;this.editOpen=true}}};</script>